"""Deterministic SYNTHETIC demonstration dataset.

Builds six simulated hours of history (02:00-08:00 IST on the demo day) for the
40-charger demo fleet, so every page has content on first launch:

* fleet snapshots every simulated minute and per-charger power/temperature
  readings every 5 minutes (from the live simulator engine itself),
* charging sessions and heartbeats generated by the engine with the fixed seed,
* eight scripted fault -> ticket stories covering every workflow state
  (open, assigned, en route, on site, resolved by technician, resolved by remote
  reset, failed reset, overdue critical, fresh critical),
* two sample policy experiments and two sample investment sites, tagged [DEMO].

Everything is created with source = "simulation" and is labelled SIMULATED in
the UI. Nothing here is real operator data.

Safety rules
------------
* Idempotent: seeding happens once (setting `demo_seeded`); restarts never
  duplicate data.
* `restore_demo` deletes ONLY simulation-source operational rows and [DEMO]
  experiment/investment rows. Imported (`operator_import`) and live
  (`operator_api`, `ocpp`) records are never touched.
"""
from __future__ import annotations

from datetime import timedelta

from sqlalchemy import delete, select
from sqlalchemy.orm import Session

from ..clock import SIM_EPOCH, wall_now
from ..config import get_settings
from ..core import finance
from ..core.policy_sim import ExperimentConfig, run_comparison
from ..models import (
    Charger, ChargerReading, ExperimentRun, FinancialReference, FleetSnapshot, InvestmentSite, SimState,
    Technician, Ticket,
)
from . import settings_store
from . import tickets as ticket_svc
from .events import record_event
from .seed import DEFAULT_SIM_PARAMS, reset_simulation, seed_reference_data
from ..tenancy import as_org, nid, sim_state

DEMO_TAG = "[DEMO]"
HISTORY_HOURS = 6
HISTORY_START = SIM_EPOCH - timedelta(hours=HISTORY_HOURS)
DEMO_VERSION = 3

# Scripted stories: simulated minute after HISTORY_START -> actions.
# Ticket numbers follow detection order (TKT-00001 .. TKT-00008).
FAULT_SCRIPT = [
    (20, "SIM-YLK-02", "ground_fault"),       # 1 stays open: overdue critical
    (45, "SIM-HSR-03", "overcurrent"),        # 2 full technician repair, resolved
    (110, "SIM-KRM-06", "payment_reader"),    # 3 remote reset succeeds
    (200, "SIM-HBL-03", "comm_loss"),         # 4 offline, reset fails, stays open
    (250, "SIM-ECY-03", "high_temperature"),  # 5 technician on site
    (290, "SIM-WFD-03", "overcurrent"),       # 6 technician en route
    (320, "SIM-YLK-04", "payment_reader"),    # 7 reset fails, assigned
    (345, "SIM-KRM-01", "ground_fault"),      # 8 fresh critical, top priority
]
# (minute, ticket index 1-based, action, extra)
WORKFLOW_SCRIPT = [
    (55, 2, "assigned", "TECH-01"), (58, 2, "en_route", None), (95, 2, "on_site", None),
    (185, 2, "resolved", "Replaced contactor relay (simulated)."),
    (195, 2, "closed", "Insulation and RCD test passed (simulated post-repair inspection)."),
    (120, 3, "reset_ok", None),
    (210, 4, "reset_fail", None),
    (255, 5, "assigned", "TECH-03"), (258, 5, "en_route", None), (300, 5, "on_site", None),
    (300, 6, "assigned", "TECH-01"), (305, 6, "en_route", None),       # overcurrent: safety-certified technician
    (330, 7, "reset_fail", None), (340, 7, "assigned", "TECH-02"),
]
SCRIPT_RESETTABLE = {3, 4, 7}


def is_seeded(db: Session) -> bool:
    return bool(settings_store.get(db, "demo_seeded", None))


def has_demo_fleet(db: Session) -> bool:
    """The session organisation really holds a SIMULATED fleet (the `demo_seeded` flag alone is not trusted)."""
    return db.scalar(select(Charger.id).where(Charger.source == "simulation").limit(1)) is not None


def demo_status(db: Session) -> dict:
    info = settings_store.get(db, "demo_seeded", None)
    return {"seeded": bool(info), "info": info, "label": "SIMULATED",
            "description": "Synthetic demonstration dataset: 6 sites, 40 chargers, 6 h of history, 8 scripted tickets."}


def should_autoseed(db: Session) -> bool:
    if not get_settings().demo_autoseed or is_seeded(db):
        return False
    # Respect an existing simulation that already has activity (e.g. an older database).
    return db.scalar(select(Ticket.id).where(Ticket.source == "simulation").limit(1)) is None


def _inject(db: Session, charger_id: str, category: str, now):
    from ..simulator.engine import inject_fault

    out = inject_fault(db, charger_id, category)
    t = db.scalar(select(Ticket).where(Ticket.code == out["ticket"])) if out["ticket"] else None
    return t


def _reset(db: Session, t: Ticket, now, ok: bool) -> None:
    c = db.get(Charger, t.charger_id)
    t.remote_reset_attempted = True
    record_event(db, c, "reset_attempt", now, payload={"type": "Soft", "ticket": t.code})
    record_event(db, c, "reset_result", now, payload={"ticket": t.code, "success": ok})
    if ok:
        record_event(db, c, "boot", now, payload={"reason": "RemoteReset"})
        ticket_svc.resolve_by_system(db, t, now, "remote_reset", "Remote reset cleared the fault.")


def build_demo(db: Session, commit_every: int | None = None) -> dict:
    """Create the demo dataset on a clean simulation of the session's organisation (system session:
    the legacy demo workspace). Caller commits. With `commit_every`, intermediate commits release the
    SQLite write lock every N steps so other organisations keep working while a workspace is built
    (a partially built workspace is simply rebuilt: it is only marked ready at the end)."""
    with as_org(db):
        return _build_demo(db, commit_every)


def _build_demo(db: Session, commit_every: int | None = None) -> dict:
    from ..simulator import engine

    seed_reference_data(db)
    state = reset_simulation(db, seed=get_settings().sim_seed, params=dict(DEFAULT_SIM_PARAMS))
    db.execute(delete(FleetSnapshot).where(FleetSnapshot.source == "simulation"))
    db.execute(delete(ChargerReading).where(ChargerReading.source == "simulation"))
    for tech in db.scalars(select(Technician)):
        tech.available = True

    # Start six hours earlier and suppress random faults/reconnects: only the
    # scripted stories happen, but sessions, heartbeats and telemetry are real
    # engine output with the fixed seed.
    state.sim_time = HISTORY_START
    state.sessions_total = 0
    for c in db.scalars(select(Charger).where(Charger.source == "simulation")):
        c.last_heartbeat_at = HISTORY_START
        c.last_event_at = HISTORY_START
        c.temp_c = 30.0
        c.power_now_kw = 0.0
        c.session_started_at = None
    warm = dict(DEFAULT_SIM_PARAMS, fault_rate_per_charger_day=0.0, reconnect_prob_per_step=0.0,
                auto_dispatch=False)
    state.params = warm
    db.flush()

    step_s = get_settings().sim_step_seconds
    steps_per_min = max(1, 60 // step_s)
    faults = {m: (nid(db, cid), cat) for m, cid, cat in FAULT_SCRIPT}
    actions: dict[int, list] = {}
    for m, idx, act, extra in WORKFLOW_SCRIPT:
        actions.setdefault(m, []).append((idx, act, extra))
    tickets: dict[int, Ticket] = {}
    total_steps = HISTORY_HOURS * 3600 // step_s

    for k in range(1, total_steps + 1):
        if commit_every and k % commit_every == 0:
            from ..db import begin_immediate
            db.commit()
            begin_immediate(db)
        engine.step(db, 1)
        if k % steps_per_min:
            continue
        minute = k // steps_per_min
        now = state.sim_time
        if minute in faults:
            cid, cat = faults[minute]
            t = _inject(db, cid, cat, now)
            if t is not None:
                idx = len(tickets) + 1
                tickets[idx] = t
                if idx in SCRIPT_RESETTABLE:
                    t.reset_due_at = None      # reset outcome is scripted below
        for idx, act, extra in actions.get(minute, []):
            t = tickets.get(idx)
            if t is None:
                continue
            if act == "reset_ok":
                _reset(db, t, now, True)
            elif act == "reset_fail":
                _reset(db, t, now, False)
            elif act == "assigned":
                ticket_svc.transition(db, t, "assigned", now, actor="demo-script", technician_id=nid(db, extra),
                                      note="Assigned by operator (scripted demo).")
            elif act == "resolved":
                ticket_svc.transition(db, t, "resolved", now, actor="demo-script", note=extra)
            elif act == "closed":
                ticket_svc.transition(db, t, "closed", now, actor="demo-script", note=extra, inspection_passed=True)
            else:
                ticket_svc.transition(db, t, act, now, actor="demo-script")
        db.flush()

    state.params = dict(DEFAULT_SIM_PARAMS)
    state.running = False
    state.speed = 4

    runs = _demo_experiments(db)
    sites = _demo_investment_sites(db)
    info = {"version": DEMO_VERSION, "created_at": wall_now().isoformat() + "Z", "seed": state.seed,
            "history_start": HISTORY_START.isoformat() + "Z", "sim_time": state.sim_time.isoformat() + "Z",
            "tickets": len(tickets), "experiment_runs": runs, "investment_sites": sites}
    settings_store.put(db, "demo_seeded", info)
    settings_store.put(db, "active_scenario", None)
    db.flush()
    return info


def _demo_experiments(db: Session) -> list[int]:
    ids = []
    for label, cfg in (
        (f"{DEMO_TAG} Baseline network (2 technicians, 0.05 faults/charger-day)",
         {"seeds": list(range(1, 11)), "days": 30}),
        (f"{DEMO_TAG} Busy network (1 technician, 0.30 faults/charger-day)",
         {"seeds": list(range(1, 11)), "days": 30, "technicians": 1, "fault_rate_per_charger_day": 0.3}),
    ):
        c = ExperimentConfig.from_dict(cfg)
        run = ExperimentRun(kind="comparison", config=c.to_dict(), config_hash=c.hash(), results=run_comparison(c),
                            label=label, data_source="simulation", created_at=wall_now())
        db.add(run)
        db.flush()
        ids.append(run.id)
    return ids


def _demo_investment_sites(db: Session) -> list[int]:
    ids = []
    for name, over, note in (
        ("Koramangala mall car park (sample)", {"lat": 12.9352, "lng": 77.6245},
         "Sample site using the default assumptions."),
        ("Electronic City highway stop (sample)",
         {"lat": 12.8452, "lng": 77.6602, "n_chargers": 4, "sessions_per_day": 30.0, "rent_monthly": 40_000},
         "Larger site with lower assumed utilisation."),
    ):
        d = finance.InvestmentInputs().to_dict()
        for k, v in over.items():
            if k in d:
                d[k] = v
        d["site_name"] = name
        try:
            inp = finance.InvestmentInputs.from_dict(d)
        except (finance.FinanceInputError, TypeError):
            inp = finance.InvestmentInputs.from_dict({"site_name": name})
        s = InvestmentSite(name=name, lat=inp.lat, lng=inp.lng, inputs=inp.to_dict(),
                           notes=f"{DEMO_TAG} {note} All inputs are ASSUMPTIONS, NOT YET VALIDATED.")
        db.add(s)
        db.flush()
        ids.append(s.id)
    return ids


def restore_demo(db: Session) -> dict:
    """Delete simulation-only data plus [DEMO] samples and rebuild the demo.
    Imported and live records are untouched. Caller commits."""
    from ..simulator import engine

    with engine.lock(), as_org(db):          # only the session's organisation (system session: legacy workspace)
        db.execute(delete(ExperimentRun).where(ExperimentRun.label.like(f"{DEMO_TAG}%")))
        kept = 0
        for s in db.scalars(select(InvestmentSite).where(InvestmentSite.notes.like(f"{DEMO_TAG}%"))).all():
            if db.scalar(select(FinancialReference.id).where(FinancialReference.investment_site_id == s.id).limit(1)):
                kept += 1      # user attached real reference figures: keep it
                continue
            db.delete(s)
        db.flush()
        info = build_demo(db)
    info["kept_demo_sites_with_references"] = kept
    return info


def autoseed_if_needed(db: Session) -> dict | None:
    if not should_autoseed(db):
        return None
    return build_demo(db)


def ensure_state(db: Session) -> SimState:
    return sim_state(db)
